  [414370] = { nil, "L'Aqua Shell di Ghamoo-ra si è incrinata!", nil, 0x2ba3a03e, "mu" },
  [414621] = { "Colpisci il cranio del bersaglio, interrompendo il lancio di incantesimi e impedendo di lanciare qualsiasi incantesimo di quella scuola per $D1.", nil, 0xf875450d, nil, "um" },
  [414644] = { "Lacera il bersaglio nemico, facendolo sanguinare e infliggendo $N1 danni in $D1, più il $N3% dei danni dell'arma per ogni applicazione di Lacerazione già presente sul bersaglio. Genera un'elevata quantità di minaccia. L'effetto si cumula fino a $N4 volte sullo stesso bersaglio.", "$N1 danni ogni $D1.", 0x58e2b595, 0x8522e0de, "uu" },
  [414673] = { "Riduce di $N1 s il tempo di recupero globale dei tuoi incantesimi Rinvigorimento, Guarigione Immediata e Crescita Rigogliosa.", nil, 0x1c2bf810, nil, "um" },
  [414677] = { "Quando curi in modo critico il bersaglio con un incantesimo di cura non periodico, pianti su di esso un Living Seed pari al $N1% della quantità curata. Il Living Seed sboccia la volta successiva che il bersaglio subisce danni o riceve una cura non periodica. Dura $D1.", nil, 0x6d9f3088, nil, "um" },
  [414680] = { nil, "Ti cura di $N1 salute la prossima volta che subisci danni o ricevi una cura non periodica.", nil, 0x96c2fb49, "mu" },
  [414683] = { "Cura un bersaglio alleato di $N1.", nil, 0xbe4c0f4a, nil, "um" },
  [414684] = { "Brucia il nemico infliggendo $N1 danni da natura e poi altri $N2 danni da natura in $D1.", "$N1 danni da natura ogni $N2 s.", 0x3aa7711e, 0x1062340a, "uu" },
  [414687] = { "Brucia il nemico infliggendo $N1 danni da natura e poi altri $N2 danni da natura in $D1.", "$N1 danni da natura ogni $N2 s.", 0x3aa7711e, 0x1062340a, "uu" },
  [414689] = { "Brucia il nemico infliggendo $N1 danni da natura e poi altri $N2 danni da natura in $D1. Fornisce $N4 punti combo.", "$N1 danni da natura ogni $N2 s.", 0x9cd4ca30, 0x1062340a, "uu" },
  [414692] = { "Ottieni l'abilità Fuoco Solare e, mentre sei in ⟦Bear Form=Forma d'Orso⟧, ⟦Cat Form=Forma Felina⟧ o ⟦Dire Bear Form=Forma d'Orso Crudele⟧, il tuo Fuoco Lunare è sostituito da Fuoco Solare (Orso) o Fuoco Solare (Felino). Questo incantesimo beneficia di tutti gli effetti associati a Fuoco Lunare e li attiva.\n\n$I1\nBrucia il nemico infliggendo $N1 danni da natura e poi altri $N2 danni da natura in $D1.\n\n$I2\nBrucia il nemico infliggendo $N4 danni da natura e poi altri $N5 danni da natura in $D2.\n\n$I3\nBrucia il nemico infliggendo $N7 danni da natura e poi altri $N8 danni da natura in $D3. Fornisce $N10 punti combo.", nil, 0xddfecf96, nil, "um" },
  [414719] = { "Alcuni dei tuoi incantesimi e delle tue abilità prolungano la durata dei tuoi effetti di danno e di cura periodici sul bersaglio:\n\nFuoco Stellare prolunga Fuoco Lunare di $D1.\nIra Silvana prolunga Fuoco Solare di $D2.\nRicrescita prolunga Rinvigorimento di $D3.\nArtigliata prolunga Squarcio di $D4.\n\nOgni effetto può essere prolungato al massimo fino alla sua durata iniziale.", nil, 0xc5b655c3, nil, "um" },
  [414722] = { nil, "Alla sua testa sembra mancare qualcosa...", nil, 0x7f7776c8, "mu" },
  [414724] = { "Risveglia uno spirito delle pianure", nil, 0x6a4a51d5, nil, "um" },
  [414730] = { nil, "Arma incantata dal vento, che conferisce attacchi aggiuntivi.", nil, 0x8a0e97c3, "mu" },
  [414760] = { nil, "Uno scudo di fulmini ti circonda e colpisce tutti gli attaccanti con danni da natura.", nil, 0xaa643f21, "mu" },
  [414799] = { "Riduce del $N1% il costo in mana di Ira Silvana e, ogni volta che infliggi danni con Ira Silvana, hai una probabilità del $N2% che il tuo prossimo lancio di ⟦Healing Touch=Tocco Curativo⟧ entro $D1 sia istantaneo e lanciabile in qualsiasi forma. Permette di lanciare Ira Silvana in forma di Albero della Vita.", nil, 0x8541d19f, nil, "um" },
  [414800] = { nil, "Il tuo prossimo ⟦Healing Touch=Tocco Curativo⟧ è istantaneo e lanciabile in qualsiasi forma.", nil, 0xc63f596d, "mu" },
